export function getModelsForBrand(brand) {
  if (!brand) return [];
  const normalized = String(brand).trim().toUpperCase();
  if (BRAND_MODELS_DATA[normalized]) return BRAND_MODELS_DATA[normalized];
  if (normalized === 'ROLLS-ROYCE' || normalized === 'ROLLS_ROYCE') return BRAND_MODELS_DATA['ROLLS'] || [];
  if (normalized === 'BMW_I' || normalized === 'BMW I') return BRAND_MODELS_DATA['BMWI'] || [];
  if (normalized === 'BMW_MOTORRAD' || normalized === 'MOTORRAD') return BRAND_MODELS_DATA['BMWMOTO'] || [];
  for (const [key, list] of Object.entries(BRAND_MODELS_DATA)) {
    if (key.toUpperCase() === normalized) return list;
  }
  return [];
}

